def graphite_dash(g, left, right, y, rise):
    pen = g.P(.79).m(left, y, "E", wm=.56)
    pen.c((left + right) * .48, y + rise * .38, "E", wm=1.18)
    pen.c(right, y + rise, "E", wm=.52)
    g.add(pen)


@glyph("hyphen", 0x002D, "punct")
def hyphen(g):
    graphite_dash(g, 0, 172, 247, 18)


@glyph("endash", 0x2013, "punct")
def en_dash(g):
    graphite_dash(g, 0, 319, 218, 38)


@glyph("emdash", 0x2014, "punct")
def em_dash(g):
    graphite_dash(g, 0, 555, 203, 55)


